from pathlib import Path
from urllib.parse import quote
import json,html
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'Organization'
apps=json.loads((OUT/'apps.json').read_text(encoding='utf-8'))
audit=json.loads((OUT/'browser-audit.json').read_text(encoding='utf-8'))['results'] if (OUT/'browser-audit.json').exists() else []
rechecks=json.loads((OUT/'browser-recheck.json').read_text(encoding='utf-8')) if (OUT/'browser-recheck.json').exists() else []
cleared={r['path'] for r in rechecks if not r['errors']}
cards=[]
for a in apps:
    path=a['path'];s=a['slug'];title=a['title'] or Path(path).stem
    group='Prompts' if any(w in path.lower() for w in ['prompt','2cntxt','ai_n8r']) else ('Creative' if any(w in path.lower() for w in ['studio','game','sprite','sound','clip','synth','ink']) else 'Apps')
    shot=OUT/'screenshots'/(s+'.png')
    picture=f'<img loading="lazy" src="Organization/screenshots/{s}.png" alt="Preview of {html.escape(title,quote=True)}">' if shot.exists() else '<div class="preview-placeholder" aria-hidden="true">'+html.escape(Path(path).stem[:2].upper())+'</div>'
    note='Advanced SEO variant' if path=='seoDashWired.html' else ('Lightweight SEO dashboard' if path=='seoDash.html' else (a['headings'][0] if a['headings'] else Path(path).stem))
    startup=any(r['path']==path and r['errors'] for r in audit) and path not in cleared
    mobile=any(r['path']==path and r['width']==390 and r.get('overflow') for r in audit)
    if startup:note='Startup error found · see browser report'
    elif mobile:note='Mobile layout needs review · '+note
    cards.append(f'<article class="card" data-category="{group}" data-search="{html.escape((title+" "+path+" "+group).lower(),quote=True)}" data-favorite="{str(path=="N8Sheetz.html").lower()}"><a class="preview" href="{quote(path,safe="/")}">{picture}</a><div class="card-body"><span class="tag">{group}</span><h3><a href="{quote(path,safe="/")}">{html.escape(title)}</a></h3><p>{html.escape(note[:110])}</p><div class="card-bottom"><a href="{quote(a["launch_path"],safe="/")}">Launch app <span aria-hidden="true">↗</span></a><a class="quiet" href="{quote(str(Path(a["organized_path"]).parent/"README.md").replace(chr(92),"/"),safe="/")}">Notes</a></div></div></article>')
favorites=[('AIWS','Organization/guides/project-boundaries.md','Server app · npm run dev'),('N8DEV','N8DEV/Dev/index.html','Development collection'),('Clark MSB','Clark MSB/index.html','Science classroom'),('AXIOM','AXIOM_CODE_AI_WORKSPACE/AXIOM_CODE_AI_WORKSPACE_v4.html','Coding workspace'),('N8Sheetz','N8Sheetz.html','Spreadsheet workspace')]
fav=''.join(f'<a class="favorite" href="{quote(p,safe="/")}"><strong>{html.escape(n)}</strong><span>{html.escape(d)}</span></a>' for n,p,d in favorites)
template='''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark"><title>Downloads | Your local workspace</title><link rel="icon" href="data:,"><style>
:root{font-family:Segoe UI,system-ui,sans-serif;color:#eaf0f8;background:#0b1018;font-synthesis:none}*{box-sizing:border-box}body{margin:0}a{color:inherit;text-decoration:none}a:hover{text-decoration:underline}button,input{font:inherit}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #85f0d1;outline-offset:5px}.skip{position:absolute;left:20px;top:-60px;background:#fff;color:#111;padding:12px;z-index:9}.skip:focus{top:12px}.wrap{max-width:1480px;margin:auto;padding:0 42px}.top{display:flex;align-items:center;justify-content:space-between;padding:26px 0;border-bottom:1px solid #273141}.brand{font-size:18px;font-weight:700;letter-spacing:.02em}.brand b{display:inline-grid;place-items:center;margin-right:12px;width:34px;height:34px;border-radius:10px;background:#84edcd;color:#112923}.top nav{display:flex;gap:22px;color:#abb9cb;font-size:14px}.hero{padding:54px 0 34px;display:flex;justify-content:space-between;gap:24px;align-items:end}.eyebrow{color:#84edcd;letter-spacing:.16em;font-size:12px;font-weight:700;text-transform:uppercase}h1{font-size:clamp(34px,4vw,58px);line-height:1.08;letter-spacing:-.04em;margin:16px 0}p{color:#aebcce;line-height:1.6}.hero p{max-width:630px;margin:0}.stat{min-width:130px;text-align:right}.stat strong{font-size:46px;display:block}.stat span{color:#91a3b9;font-size:13px}.section-title{display:flex;justify-content:space-between;align-items:center;margin:22px 0 16px}h2{font-size:19px;margin:0}.section-title span{color:#91a3b9;font-size:13px}.favorites{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.favorite{background:#14221f;border:1px solid #29443c;border-radius:13px;padding:20px 16px;min-width:0}.favorite strong,.favorite span{display:block}.favorite strong{font-size:16px}.favorite span{font-size:12px;color:#adbfba;margin-top:8px;line-height:1.5}.library{margin-top:40px}.toolbar{display:flex;justify-content:space-between;gap:20px;margin:20px 0}.filters{display:flex;gap:8px;flex-wrap:wrap}.filters button{cursor:pointer;border:1px solid #2c3749;background:transparent;color:#bdcadd;border-radius:8px;padding:10px 15px}.filters button[aria-pressed=true]{background:#e8f0fa;color:#15202e;border-color:#e8f0fa}label.search{display:flex;align-items:center;gap:10px;font-size:14px;color:#adbed1}input{color:#eaf0f8;background:#141d2a;border:1px solid #344055;border-radius:8px;padding:11px 13px;width:260px;max-width:100%}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}.card{background:#141c28;border:1px solid #263247;border-radius:15px;overflow:hidden;min-width:0}.preview{display:block;height:172px;background:#1d2c3d;overflow:hidden}.preview img{width:100%;height:100%;object-fit:cover;object-position:top}.preview-placeholder{height:100%;display:grid;place-items:center;color:#8bacce;font-size:44px;font-weight:800;background:linear-gradient(130deg,#223d48,#1a2237)}.card-body{padding:20px}.tag{font-size:10px;text-transform:uppercase;letter-spacing:.13em;color:#8de5ce}h3{font-size:17px;line-height:1.35;margin:10px 0;overflow-wrap:anywhere}.card-body p{font-size:13px;min-height:42px;margin:0 0 20px;overflow-wrap:anywhere}.card-bottom{border-top:1px solid #2a3546;padding-top:14px;display:flex;justify-content:space-between;font-size:12px;color:#b9f4e3;gap:8px}.quiet{color:#a7b6ca}#empty{padding:40px;border:1px dashed #3a4e67;border-radius:12px}.footer{margin:40px 0 28px;border-top:1px solid #263247;padding-top:22px;display:flex;justify-content:space-between;gap:16px;color:#91a3b9;font-size:12px;line-height:1.6}[hidden]{display:none!important}@media(max-width:1100px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}.favorites{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:760px){.wrap{padding:0 20px}.top{align-items:start;gap:16px}.top nav{flex-direction:column;gap:8px;font-size:12px}.hero{padding:36px 0 22px}.stat{display:none}.favorites{grid-template-columns:repeat(2,minmax(0,1fr))}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.toolbar{flex-direction:column}.search input{flex:1}.preview{height:130px}.card-body{padding:14px}h3{font-size:15px}.footer{flex-direction:column}}@media(max-width:440px){.grid{grid-template-columns:1fr}.preview{height:190px}.hero p{font-size:14px}.section-title span{font-size:11px}.filters button{padding:9px 12px}}
</style></head><body><a class="skip" href="#library">Skip to apps</a><div class="wrap"><header class="top"><a class="brand" href="Downloads-Launcher.html"><b aria-hidden="true">D</b>Downloads</a><nav aria-label="Workspace"><a href="Organization/PROJECT-INDEX.md">Project index</a><a href="Organization/IMPLEMENTATION-STATUS.md">Implementation report</a><a href="Organization/CLEANUP-REVIEW.md">Cleanup review</a></nav></header><main><section class="hero"><div><div class="eyebrow">Your local workspace</div><h1>A place for every idea.</h1><p>Your apps, creative tools, and active projects — organized and ready to open.</p></div><div class="stat"><strong>__COUNT__</strong><span>apps in your library</span></div></section><section aria-labelledby="fav-title"><div class="section-title"><h2 id="fav-title">Keep close</h2><span>Five starting favorites</span></div><div class="favorites">__FAVORITES__</div></section><section class="library" id="library" aria-labelledby="library-title"><div class="section-title"><h2 id="library-title">App library</h2><span id="count" role="status" aria-live="polite">__COUNT__ apps</span></div><div class="toolbar"><div class="filters" role="group" aria-label="Filter apps"><button type="button" data-filter="All" aria-pressed="true">All apps</button><button type="button" data-filter="Prompts" aria-pressed="false">Prompts</button><button type="button" data-filter="Creative" aria-pressed="false">Creative</button><button type="button" data-filter="Apps" aria-pressed="false">Other apps</button></div><label class="search">Search <input id="search" type="search" placeholder="Find an app…" autocomplete="off"></label></div><div class="grid">__CARDS__</div><p id="empty" hidden>No apps match. Clear your search or choose All apps.</p></section></main><footer class="footer"><span>Local files · Existing app addresses preserved<br>Some apps need an internet connection for libraries or services.</span><span><a href="Organization/guides/sync-and-privacy.md">Storage notes</a> · <a href="Organization/RESTORE.md">Restore guide</a></span></footer></div><script>
const cards=[...document.querySelectorAll('.card')],filters=[...document.querySelectorAll('[data-filter]')],search=document.getElementById('search');let current='All';function apply(){const q=search.value.trim().toLowerCase();let n=0;for(const card of cards){const show=(current==='All'||card.dataset.category===current)&&card.dataset.search.includes(q);card.hidden=!show;if(show)n++;}document.getElementById('count').textContent=n+' '+(n===1?'app':'apps');document.getElementById('empty').hidden=n!==0;}for(const b of filters)b.addEventListener('click',()=>{current=b.dataset.filter;for(const x of filters)x.setAttribute('aria-pressed',String(x===b));apply();});search.addEventListener('input',apply);
</script></body></html>'''
(ROOT/'Downloads-Launcher.html').write_text(template.replace('__COUNT__',str(len(apps))).replace('__FAVORITES__',fav).replace('__CARDS__',''.join(cards)),encoding='utf-8')
print('Launcher written:',len(apps),'apps')
